include { NGSCHECKMATE_FASTQ  } from 'nf-core/ngscheckmate/fastq'
include { NGSCHECKMATE_VAFNCM } from 'nf-core/ngscheckmate/vafncm'

workflow FASTQ_NGSCHECKMATE {
    take:
    ch_fastq  // channel: [ val(meta1), fastq ]
    ch_snp_pt // channel: [ val(meta2), snp_pt ]

    main:
    NGSCHECKMATE_FASTQ(ch_fastq, ch_snp_pt.first())

    NGSCHECKMATE_FASTQ.out.vaf.map { _meta, vaf -> vaf }.collect().map { files -> [files] }.set { ch_collected_vafs }

    ch_snp_pt
        .map { meta, _snp_pt -> meta }
        .combine(ch_collected_vafs)
        .set { ch_vafs }

    NGSCHECKMATE_VAFNCM(ch_vafs)

    emit:
    corr_matrix = NGSCHECKMATE_VAFNCM.out.corr_matrix // channel: [ meta, corr_matrix ]
    matched     = NGSCHECKMATE_VAFNCM.out.matched     // channel: [ meta, matched ]
    all         = NGSCHECKMATE_VAFNCM.out.all         // channel: [ meta, all ]
    vaf         = NGSCHECKMATE_FASTQ.out.vaf          // channel: [ meta, vaf ]
    pdf         = NGSCHECKMATE_VAFNCM.out.pdf         // channel: [ meta, pdf ], optional
}

nextflow_workflow {

    name "Test Workflow FASTQ_NGSCHECKMATE"
    script "../main.nf"
    workflow "FASTQ_NGSCHECKMATE"

    tag "subworkflows"
    tag "subworkflows_nfcore"
    tag "subworkflows/fastq_ngscheckmate"
    tag "ngscheckmate"
    tag "ngscheckmate/fastq"
    tag "ngscheckmate/vafncm"

    test("fastq_ngscheckmate") {

        when {

            workflow {
                """
                input[0] = Channel.of (
                    [
                        [ id:'test1' ],
                            [
                                file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true),
                                file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_2.fastq.gz', checkIfExists: true)
                            ]
                    ],
                    [
                        [ id:'test2' ],
                            [
                                file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test2_1.fastq.gz', checkIfExists: true),
                                file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test2_2.fastq.gz', checkIfExists: true)
                            ]
                    ],
                    [
                        [ id:'test3' ],
                            [
                                file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test.methylated_1.fastq.gz', checkIfExists: true),
                                file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test.methylated_2.fastq.gz', checkIfExists: true)
                            ]
                    ]
                )
                input[1] = Channel.value([
                        [ id:'snp_pt' ],
                        [
                            file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/ngscheckmate//SNP.pt', checkIfExists: true)
                        ]
                    ])
                """
            }
        }
        then {
            assertAll(
                { assert workflow.success },
                { assert snapshot(
                    workflow.out.corr_matrix,
                    workflow.out.matched,
                    workflow.out.all,
                    workflow.out.vaf,
                    file(workflow.out.pdf[0][1]).name
                    ).match() }
            )
        }
    }

    test("fastq_ngscheckmate - stub") {
        options '-stub'
        when {

            workflow {
                """
                input[0] = Channel.of (
                    [
                        [ id:'test1' ],
                            [
                                file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true),
                                file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_2.fastq.gz', checkIfExists: true)
                            ]
                    ],
                    [
                        [ id:'test2' ],
                            [
                                file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test2_1.fastq.gz', checkIfExists: true),
                                file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test2_2.fastq.gz', checkIfExists: true)
                            ]
                    ],
                    [
                        [ id:'test3' ],
                            [
                                file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test.methylated_1.fastq.gz', checkIfExists: true),
                                file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test.methylated_2.fastq.gz', checkIfExists: true)
                            ]
                    ]
                )
                input[1] = Channel.value([
                        [ id:'sarscov2' ],
                        [
                            file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/ngscheckmate/SNP.pt', checkIfExists: true)
                        ]
                    ])
                """
            }
        }
        then {
            assertAll(
                { assert workflow.success },
                { assert snapshot(
                    workflow.out
                ).match() }
            )
        }
    }

}
